What will be the output of the following code snippet?
for (int i = 1; i <= 3; i++) {
    for (int j = 1; j <= i; j++) {
        printf("*");
    }
    printf("\n");
}

What is the output of the following code snippet for matrix multiplication of two 2x2 matrices A and B?
int A[2][2] = {{1, 2}, {3, 4}};
int B[2][2] = {{5, 6}, {7, 8}};
int C[2][2];
for (int i = 0; i < 2; i++) {
    for (int j = 0; j < 2; j++) {
        C[i][j] = 0;
        for (int k = 0; k < 2; k++) {
            C[i][j] += A[i][k] * B[k][j];
        }
    }
}

What is the output of the following recursive function when called with `factorial(5)`?
int factorial(int n) {
    if (n == 0) return 1;
    return n * factorial(n - 1);
}

Which of the following is the correct way to access the `age` member of the `student` structure within a `class` structure in C?
struct student {
    int age;
};
struct class {
    struct student s;
};
struct class c;

What is the output of the following program?
void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}
int main() {
    int x = 5, y = 10;
    swap(&x, &y);
    printf("%d %d", x, y);
    return 0;
}

